НомерДиагноза = 1;
Текст = "";
ТЧ = Объект.Диагнозы;
Для Каждого Стр Из ТЧ Цикл
	Если ТЧ.Количество() > 1 Тогда
		Текст = Символы.ПС + Текст + Строка(НомерДиагноза) + ". ";
		НомерДиагноза = НомерДиагноза + 1;
	КонецЕсли;

	Если ЗначениеЗаполнено(Стр.Диагноз.КодДиагноза) Тогда
		МКБ = "[" + Стр.Диагноз.КодДиагноза + "] ";
	Иначе
		МКБ = "";
	КонецЕсли;

	Диагноз = Стр.Диагноз.Наименование;
	Описание = Стр.Детализация;
	Сопутствующий = Стр.Сопутствующий;
	К1 = Строка(Стр.Классификация1);
	К2 = Строка(Стр.Классификация2);
	К3 = Строка(Стр.Классификация3);
	Травма = Стр.Травма.Наименование;
	Исход = ?(Стр.Исход.ПолноеНаименование <> "", Стр.Исход.ПолноеНаименование, Стр.Исход.Наименование);

	Если ЗначениеЗаполнено(МКБ + Диагноз) Тогда 
		Текст = Текст + "Диагноз: " + МКБ + Диагноз + "<br>";
	КонецЕсли;

	Если ЗначениеЗаполнено(Описание) Тогда
		Текст = Текст + "Описание: " + Описание + "<br>";
	КонецЕсли;

	Если ЗначениеЗаполнено(Сопутствующий) Тогда
		Текст = Текст + "Сопутствующий: " + Сопутствующий + "<br>";
	КонецЕсли;

	Если ЗначениеЗаполнено(К1 + К2 + К3) Тогда
		Текст = Текст + "Классификация: "; 
	КонецЕсли;

	Если ЗначениеЗаполнено(К1) Тогда
		Текст = Текст + К1 + ", ";
	КонецЕсли;

	Если ЗначениеЗаполнено(К2) Тогда
		Текст = Текст + К2 + ", ";
	КонецЕсли;

	Если ЗначениеЗаполнено(К3) Тогда
		Текст = Текст + К3;
	КонецЕсли;

	Если ЗначениеЗаполнено(К1 + К2 + К3) Тогда
		Текст = Текст + "<br>"; 
	КонецЕсли;

	Если ЗначениеЗаполнено(Травма) Тогда
		Текст = Текст + "Вид нетрудоспособности: " + Травма;
	КонецЕсли;

	Если ЗначениеЗаполнено(Исход) Тогда
		Если Травма <> "" Тогда
			Текст = Текст + ", ";
		КонецЕсли;
		Текст = Текст + "Исход диагноза: " + Исход;
	КонецЕсли;

	Если ЗначениеЗаполнено(Травма + Исход) Тогда
		Текст = Текст + "<br>"; 
	КонецЕсли;

КонецЦикла;

Результат = Текст;

// Шапка
Текст = "<TABLE border=""1"" cellpadding=""3"" style=""border-color: inherit; border-style: solid; border-collapse: collapse; width: 100%;"">
		|<TBODY>
		|<TR>
		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>Наименование услуги</P></TD>
		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>Дата</P></TD>
		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>Назначено</P></TD>
		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>Комментарий</P></TD></TR>";

Для Каждого СтрокаПлана Из ПланЛечения Цикл

	Текст = Текст + "<TR>";

	Услуга = Строка(СтрокаПлана.Номенклатура);

	Дата = ?(СтрокаПлана.Дата = НачалоДня(СтрокаПлана.Дата), Формат(СтрокаПлана.Дата, "ДФ=dd.MM.yyyy"), Строка(СтрокаПлана.Дата));
	Если СтрокаПлана.Дата = Дата(1,1,1) Тогда
		Дата = "&nbsp;";
	КонецЕсли;

	Назначено = ?(СтрокаПлана.Количество = 0, "&nbsp;", Строка(СтрокаПлана.Количество));
	Комментарий = ?(ПустаяСтрока(СтрокаПлана.Комментарий), "&nbsp;", СтрокаПлана.Комментарий);

	Текст = Текст + "<TD style='WORD-WRAP: break-word'><P>" + Услуга + "</TD>";
	Текст = Текст + "<TD align=center>" + Дата + "</TD>";
	Текст = Текст + "<TD style='WORD-WRAP: break-word' align=center>" + Назначено + "</TD>";
	Текст = Текст + "<TD style='WORD-WRAP: break-word' align=center>" + Комментарий + "</TD></TR>";

КонецЦикла;

Текст = Текст + "</TBODY></TABLE>";

Результат = Текст;

// Заголовок над таблицей
ЗаголовокТаблицы = "Медикаментозное лечение";

// Текст над таблицей и шапка таблицы
ТекстШапки = ЗаголовокТаблицы + "
		|<TABLE border=""1"" cellpadding=""3"" style=""border-color: inherit; border-style: solid; border-collapse: collapse; width: 100%;"">
		|<TBODY>
		|<TR>
		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>Медикаменты</P></TD>
		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>Период с</P></TD>
		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>До</P></TD>
		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>Разовая доза</P></TD>
		|<TD style='WORD-WRAP: break-word'>
//		|<P align=center>Ед. изм.</P></TD>
//		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>Приемов в день</P></TD>
		|<TD style='WORD-WRAP: break-word'>
		|<P align=center>Комментарий</P></TD></TR>";

ТекстШапкиДобавлен = Ложь;

Текст = "";

Для Каждого СтрокаПлана Из ПланЛечения Цикл   

	Если СтрокаПлана.ВидЭлемента <> ПредопределенноеЗначение("Перечисление.ВидыНазначений.Медикаменты") Тогда
		Продолжить;
	КонецЕсли;
	
	Текст = Текст + "<TR>";
	Медикамент = Строка(СтрокаПлана.Номенклатура);
	Медикамент = ?(ПустаяСтрока(Медикамент), "&nbsp;", Медикамент);
	
	Дата = ?(СтрокаПлана.Дата = НачалоДня(СтрокаПлана.Дата), Формат(СтрокаПлана.Дата, "ДФ=dd.MM.yyyy"), Строка(СтрокаПлана.Дата));
	Если СтрокаПлана.Дата = Дата(1,1,1) Тогда
		Дата = "&nbsp;";
	КонецЕсли;
	ДатаОкончания = ?(СтрокаПлана.ДатаОкончания = НачалоДня(СтрокаПлана.ДатаОкончания), Формат(СтрокаПлана.ДатаОкончания, "ДФ=dd.MM.yyyy"), Строка(СтрокаПлана.ДатаОкончания));
	Если СтрокаПлана.ДатаОкончания = Дата(1,1,1) Тогда
		ДатаОкончания = "&nbsp;";
	КонецЕсли;
	Дозировка = ?(СтрокаПлана.Дозировка = 0, "&nbsp;", Строка(СтрокаПлана.Дозировка));
	ЕдиницаИзмерения = Строка(СтрокаПлана.ЕдиницаИзмерения);
	ПриемовВДень = ?(ПустаяСтрока(СтрокаПлана.ПриемовВДень), "&nbsp;", СтрокаПлана.ПриемовВДень);
	Комментарий = ?(ПустаяСтрока(СтрокаПлана.Комментарий), "&nbsp;", СтрокаПлана.Комментарий);
	
	ТекстСтроки = "";
	ТекстСтроки = ТекстСтроки + "<TD style='WORD-WRAP: break-word'><P>" + Медикамент + "</TD>";
	ТекстСтроки = ТекстСтроки + "<TD align=center>" + Дата + "</TD>";
	ТекстСтроки = ТекстСтроки + "<TD align=center>" + ДатаОкончания + "</TD>";
	ТекстСтроки = ТекстСтроки + "<TD style='WORD-WRAP: break-word' align=center>" + Дозировка + " " + ЕдиницаИзмерения + "</TD>";
//	ТекстСтроки = ТекстСтроки + "<TD style='WORD-WRAP: break-word' align=center>" + ЕдиницаИзмерения + "</TD>";
	ТекстСтроки = ТекстСтроки + "<TD style='WORD-WRAP: break-word' align=center>" + ПриемовВДень + "</TD>";
	ТекстСтроки = ТекстСтроки + "<TD style='WORD-WRAP: break-word' align=center>" + Комментарий + "</TD></TR>";
	
	Если Не ТекстШапкиДобавлен Тогда
		Текст = Текст + ТекстШапки;
		ТекстШапкиДобавлен = Истина;
	КонецЕсли;
	Текст = Текст + ТекстСтроки;
	
КонецЦикла;

Если ТекстШапкиДобавлен Тогда
	Текст = Текст + "</TBODY></TABLE>";
КонецЕсли;

Результат = Текст;

// Заголовок над таблицей
ЗаголовокТаблицы = "Назначения";
// Текст над таблицей и шапка таблицы
ТекстШапки = ЗаголовокТаблицы + "
			|<TABLE border=1 cellspacing='0'>
			|<TBODY>
			|<TR>
			|<TD style='WORD-WRAP: break-word'>
			|<P align=center>Наименование услуги</P></TD>
			|<TD style='WORD-WRAP: break-word'>
			|<P align=center>Дата</P></TD>
			|<TD style='WORD-WRAP: break-word'>
			|<P align=center>Комментарий</P></TD></TR>";
ТекстШапкиДобавлен = Ложь;
Текст = "";
// Строки таблицы
Для Каждого Строка Из ПланЛечения Цикл   
	Текст = Текст + "<TR>";
	Если Не (ТипЗнч(Строка.Номенклатура) = Тип("СправочникСсылка.Номенклатура")
				И РаботаСФормамиСервер.ЭтоМатериал(Строка.Номенклатура))
	Тогда
		Текст = Текст + "<TR>";
		Если Строка.ВидЭлемента = Перечисления.ВидыНазначений Тогда
			Услуга = "Консультация врача специализации """ + Строка.Номенклатура.Наименование + """";
		ИначеЕсли ЗначениеЗаполнено(Строка.Номенклатура) Тогда
			Услуга = Строка.Номенклатура.Наименование;
		Иначе
			Услуга = "";
		КонецЕсли;	
		Дата = ?(Строка.Дата = НачалоДня(Строка.Дата), Формат(Строка.Дата, "ДФ=dd.MM.yyyy"), Строка(Строка.Дата));
		Если Строка.Дата = Дата(1,1,1) Тогда
			Дата = "&nbsp;";
		КонецЕсли;       
		Комментарий = ?(ПустаяСтрока(Строка.Комментарий), "&nbsp;", Строка.Комментарий);
		ТекстСтроки = "";
		ТекстСтроки = ТекстСтроки + "<TD style='WORD-WRAP: break-word'><P>" + Услуга + "</TD>";
		ТекстСтроки = ТекстСтроки + "<TD align=center>" + Дата + "</TD>";
		ТекстСтроки = ТекстСтроки + "<TD style='WORD-WRAP: break-word' align=center>" + Комментарий + "</TD></TR>";
		Если Не ТекстШапкиДобавлен Тогда
			Текст = Текст + ТекстШапки;
			ТекстШапкиДобавлен = Истина;
		КонецЕсли;
		Текст = Текст + ТекстСтроки;
	КонецЕсли;
КонецЦикла;
Если ТекстШапкиДобавлен Тогда
	Текст = Текст + "</TBODY></TABLE>";
КонецЕсли;
Результат = Текст;

Док = ДокументОбъект;
Тип = Перечисления.ТипыКонтактнойИнформации.Адрес;
спрВиды = Справочники.ВидыКонтактнойИнформации;
Результат = Справочники.Филиалы.ПолучитьКИ(Док.Филиал,Тип, спрВиды.АдресПочтовый);
Если Не ЗначениеЗаполнено(Результат) Тогда
	Результат = Справочники.Филиалы.ПолучитьКИ(Док.Филиал,Тип, спрВиды.АдресФактический);
КонецЕсли;Если Не ЗначениеЗаполнено(Результат) Тогда
	Результат = Справочники.Филиалы.ПолучитьКИ(Док.Филиал,Тип, спрВиды.АдресЮридический);
КонецЕсли;

Док = ДокументОбъект;
Фамилия = СокрЛП(Док.Клиент.Фамилия);
Имя = СокрЛП(Док.Клиент.Имя);
Отчество = СокрЛП(Док.Клиент.Отчество);
Результат = Фамилия + Символы.НПП + Имя + Символы.НПП + Отчество;

Док = ДокументОбъект;
Фамилия = СокрЛП(Док.Клиент.Фамилия);
Имя = Лев(СокрЛП(Док.Клиент.Имя), 1);
Отчество = Лев(СокрЛП(Док.Клиент.Отчество), 1);
Если ЗначениеЗаполнено(Имя) Тогда
	Имя = Имя + ".";
КонецЕсли;
Если ЗначениеЗаполнено(Отчество) Тогда
	Отчество = Отчество + ".";
КонецЕсли;
Результат = Фамилия + Символы.НПП + Имя + Символы.НПП + Отчество;

Клиент = ДокументОбъект.Клиент;
Результат = "";
// Возвращает полную форму представления адреса за исключением индекса.
// Получаем фактический адрес. Если его нет, то юридический.
Запись = РегистрыСведений.КонтактнаяИнформация.СоздатьМенеджерЗаписи();
Запись.Объект = Клиент;
Запись.Тип = Перечисления.ТипыКонтактнойИнформации.Адрес;
Запись.Вид = Справочники.ВидыКонтактнойИнформации.АдресФактический;
Запись.Прочитать();
Если Не Запись.Выбран() Тогда
	Запись.Объект = Клиент;
	Запись.Тип = Перечисления.ТипыКонтактнойИнформации.Адрес;
	Запись.Вид = Справочники.ВидыКонтактнойИнформации.АдресЮридический;
	Запись.Прочитать();
КонецЕсли;	
Если Запись.Выбран() Тогда
	// Адрес найден
	Если Не ЗначениеЗаполнено(Запись.ЗначенияПолей) Тогда
		Запись = КонтактнаяИнформацияСервер.ОбновитьКИПодФорматФИАС(Клиент, Запись.Вид);	
	КонецЕсли;	
	ВидИнформации = Новый Структура("ФорматАдреса, ВключатьИндексВПредставление", "ФИАС", Ложь);
	ВидИнформации.Вставить("ВключатьСтрануВПредставление", Ложь); // Вывод страны в адресе не осуществлять.	
	АдресXDTO = УправлениеКонтактнойИнформациейСлужебный.КонтактнаяИнформацияИзXML(Запись.ЗначенияПолей);
	АдресXDTO.Состав.Состав.КраткоеПредставление = Ложь;
	Представление = УправлениеКонтактнойИнформациейСлужебный.ПредставлениеАдреса(АдресXDTO.Состав, ВидИнформации);	
	Результат = Представление;
КонецЕсли;

СтруктураАдреса = МедицинскаяДеятельность.ПолучитьАдресКлиентаДляМедкарты(ДокументОбъект.Клиент, Ложь);Результат = СтруктураАдреса.Дом;

Если ЗначениеЗаполнено(СтруктураАдреса.Корпус) Тогда
	Результат = Результат + "-" + СтруктураАдреса.Корпус;
КонецЕсли;

Результат = "";
Выборка = Справочники.СтраховыеПолисы.Выбрать(,ДокументОбъект.Клиент);
Пока Выборка.Следующий() Цикл
	Если Не Выборка.НеДействителен
		 И Выборка.СрокДействияНачало <= ДокументОбъект.Дата
		 И Выборка.СрокДействия >= ДокументОбъект.Дата
		 И Не Выборка.ПометкаУдаления
		 И Выборка.ВидПолиса.Тип = Перечисления.ТипыСтраховыхПрограмм.ОМС 
	Тогда
		Результат = СокрЛП(Выборка.Серия + " " + Выборка.Номер);
		Прервать;
	КонецЕсли;
КонецЦикла;

// Заголовок над таблицей
ЗаголовокТаблицы = "Лекарственная непереносимость:";

// Текст над таблицей и шапка таблицы
ТекстШапки = ЗаголовокТаблицы + "
			|<TABLE border=1  cellspacing='0' width = '100%'>
			|<TBODY>
			|<TR>
			|<TD style='font-size: 12pt; WORD-WRAP: break-word; width: 40%'>
			|<P align=center>Действующее вещество</P></TD>
			|<TD style='font-size: 12pt; WORD-WRAP: break-word'>
			|<P align=center>Реакция</P></TD></TR>";

ТекстШапкиДобавлен = Ложь;
Текст = "";
Клиент = ДокументОбъект.Клиент;
Запрос=Новый Запрос;
Запрос.УстановитьПараметр("Клиент", Клиент); 
Запрос.Текст ="ВЫБРАТЬ 
              |	РегистрСведенийЛекарственнаяНепереносимость.ДействующееВещество,
              |	РегистрСведенийЛекарственнаяНепереносимость.Реакция
              |ИЗ
              |	РегистрСведений.ЛекарственнаяНепереносимость КАК РегистрСведенийЛекарственнаяНепереносимость
              |ГДЕ
              |	РегистрСведенийЛекарственнаяНепереносимость.Клиент = &Клиент";
			  
ЛекарственнаяНепереносимость=Запрос.Выполнить().Выгрузить();

Для Каждого СтрокаНепереносимости Из ЛекарственнаяНепереносимость Цикл
	
	Текст = Текст + "<TR>";
	ДействующееВещество=СтрокаНепереносимости.ДействующееВещество;
	Реакция=СтрокаНепереносимости.Реакция;
	Если СокрЛП(ДействующееВещество)="" Тогда 
		ДействующееВещество="&nbsp;"
	КонецЕсли;
	Если СокрЛП(Реакция)= "" Тогда 
		Реакция="&nbsp;"
	КонецЕсли;

	ТекстСтроки = "";
	ТекстСтроки = ТекстСтроки + "<TD   style='font-size: 12pt;WORD-WRAP: break-word; width: 40%'><P>" + ДействующееВещество + "</TD>"; 
	ТекстСтроки = ТекстСтроки + "<TD   style='font-size: 12pt;WORD-WRAP: break-word' align=center><P>" + Реакция + "</TD></TR>";
	
	Если Не ТекстШапкиДобавлен Тогда
		Текст = Текст + ТекстШапки;
		ТекстШапкиДобавлен = Истина;
	КонецЕсли;
	Текст = Текст + ТекстСтроки;
КонецЦикла;

Если ТекстШапкиДобавлен Тогда
	Текст = Текст + "</TBODY></TABLE>";
КонецЕсли;

Результат = Текст;

Клиент = ДокументОбъект.Клиент;

ДанныеКлиентов = Новый Соответствие;
СписокКлиентов = Новый Массив;
СписокКлиентов.Добавить(Клиент);

КалендарьПланирования.ОбновитьКэшДопИнформацииКлиентов(ДанныеКлиентов,СписокКлиентов);
ДанныеКлиента = ДанныеКлиентов.Получить(Клиент);
Если ДанныеКлиента = Неопределено Тогда
	Результат = "";
ИначеЕсли ДанныеКлиента.Свойство("СотовыйТелефон") Тогда
	Результат = ДанныеКлиента.СотовыйТелефон;
ИначеЕсли ДанныеКлиента.Свойство("Телефон") Тогда
	Результат = ДанныеКлиента.Телефон;
