Клиент = ДокументОбъект.Клиент;

Запрос = Новый Запрос;
Запрос.Текст ="ВЫБРАТЬ
| АнамнезЖизни.Параметр,
| АнамнезЖизни.Значение
|ИЗ
| РегистрСведений.АнамнезыЖизни.СрезПоследних(, Клиент = &Клиент) КАК АнамнезЖизни";

Запрос.УстановитьПараметр("Клиент", Клиент); 
ВыборкаЗапроса = Запрос.Выполнить().Выбрать(); 

Если ВыборкаЗапроса.Количество() <> 0 Тогда
	
	Текст = "<TABLE style='BORDER-COLLAPSE: collapse;  margin-left=10pt'  bordercolor='black' border='0' width='100%'>
	|<TBODY>";
	
	Попытка
		Если ЗначениеЗаполнено(Заголовок) Тогда
			Текст = Заголовок + "<BR>" + Текст;
		КонецЕсли;
	Исключение КонецПопытки;
	
	ШаблонЯчейки = "<TD valign='top' style='WORD-WRAP: break-word'>%ТекстПараметр</TD>";
	
	НомерКолонки = 1;
	ВсегоКолонок = 2;
	КонецВыборки = Ложь;
	
	Пока Истина Цикл
		
		Если ВыборкаЗапроса.Следующий() Тогда
			ТекстПараметр = СокрЛП(Строка(ВыборкаЗапроса.Параметр)) + ": " + Строка(ВыборкаЗапроса.Значение);
		Иначе
			КонецВыборки = Истина;
			ТекстПараметр = "";
		КонецЕсли;
		
		// Начало строки.
		Если НомерКолонки = 1 Тогда
			Если КонецВыборки Тогда
				Прервать;
			Иначе
				Текст = Текст + "<TR>"; // Начинаем новую строку.
			КонецЕсли;
		КонецЕсли;
		
		Текст = Текст + СтрЗаменить(ШаблонЯчейки, "%ТекстПараметр", ТекстПараметр);
		
		// Конец строки.
		Если НомерКолонки = ВсегоКолонок Тогда
			Текст = Текст + "</TR>";
		КонецЕсли;
		
		НомерКолонки = ?(НомерКолонки < ВсегоКолонок, НомерКолонки + 1, 1);
		
	КонецЦикла;
	
	Текст = Текст + "</TBODY></TABLE>";
	Результат = Текст;
	
КонецЕсли;
